mapper.select:
SELECT, a.approval_status AS approvalStatus, a.contract_id AS contractId, a.payment_id AS paymentId FROM cr_repay_plan_draft a LEFT JOIN ( SELECT id, business_key, create_time, update_time, contract_id, proc_business_key, report_state, approval_status, payment_id, payment_apply_code, phase, collection_amount, collection_principal, pay_date FROM cr_actual_repay_draft
AND report_state = #{query.reportState}
AND approval_status = #{query.approvalStatus}
AND payment_id IN (SELECT payment_id FROM cr_account_draft cad WHERE cad.report_flag = 1)
AND proc_business_key = #{query.procBusinessKey}
) b ON a.payment_apply_code = b.payment_apply_code AND a.phase = b.phase LEFT JOIN cr_account_draft account ON account.payment_apply_code = a.payment_apply_code WHERE a.is_show = 1
AND a.report_state = #{query.reportState}
AND a.approval_status = #{query.approvalStatus}
AND a.payment_id IN (SELECT payment_id FROM cr_account_draft cad WHERE cad.report_flag = 1)
AND a.proc_business_key = #{query.procBusinessKey}

SELECT , a.contract_id as contractId FROM cr_repay_plan_proc_snap a LEFT JOIN ( SELECT id, business_key, create_time, update_time, contract_id, proc_business_key, batch_id, batch_no, payment_id, payment_apply_code, phase, collection_amount, collection_principal, pay_date FROM cr_actual_repay_proc_snap
AND batch_id = #{query.batchId}
AND proc_business_key = #{query.procBusinessKey}
AND payment_apply_code LIKE CONCAT('%', #{query.paymentApplyCode}, '%')
AND payment_id = #{query.paymentId}
) b ON a.payment_apply_code = b.payment_apply_code AND a.phase = b.phase LEFT JOIN cr_account_draft account ON account.payment_apply_code = a.payment_apply_code WHERE a.is_show = 1
AND a.batch_id = #{query.batchId}
AND a.batch_id = #{query.batchId}
AND a.proc_business_key = #{query.procBusinessKey}

SELECT , a.contract_id AS contractId FROM cr_repay_plan_full_snap a LEFT JOIN cr_actual_repay_full_snap b ON a.payment_apply_code = b.payment_apply_code AND a.phase = b.phase LEFT JOIN cr_account_draft account ON account.payment_apply_code = a.payment_apply_code WHERE 1 = 1
AND b.batch_id = #{query.batchId}
AND a.batch_id = #{query.batchId}
